const initialSessions=[{id:1,device:"Windows Desktop",browser:"Google Chrome 138",os:"Windows 11",location:"Karnal, Haryana, India",ip:"103.21.120.52",loginTime:"22 Jul 2026 \u2022 09:35 AM",logoutTime:null,status:"Online",isCurrent:!0},{id:2,device:"Samsung Galaxy S24",browser:"Chrome Mobile",os:"Android 15",location:"Delhi, India",ip:"49.37.215.121",loginTime:"20 Jul 2026 \u2022 05:18 PM",logoutTime:"20 Jul 2026 \u2022 08:42 PM",status:"Logged Out",isCurrent:!1},{id:3,device:"MacBook Pro",browser:"Safari",os:"macOS Sequoia",location:"Mumbai, India",ip:"182.71.55.18",loginTime:"18 Jul 2026 \u2022 11:15 AM",logoutTime:null,status:"Online",isCurrent:!1}],listContainer=document.getElementById("session-list");function renderSessions(n){if(listContainer.innerHTML="",n.length===0){listContainer.innerHTML='<p class="session-meta">No active secondary sessions found.</p>';return}n.forEach(i=>{const o=document.createElement("div");o.className="session-item",o.innerHTML=`
<div class="session-card">

    <div class="top-row">

        <div class="device-name">
            \u{1F4BB} ${i.device}

            ${i.isCurrent?'<span class="badge">Current Device</span>':""}

        </div>

        <span class="${i.status==="Online"?"online":"offline"}">

            ${i.status}

        </span>

    </div>

    <div class="details">

        <div><strong>\u{1F310} Browser:</strong> ${i.browser}</div>

        <div><strong>\u{1F4BB} OS:</strong> ${i.os}</div>

        <div><strong>\u{1F4CD} Location:</strong> ${i.location}</div>

        <div><strong>\u{1F30D} IP:</strong> ${i.ip}</div>

        <div><strong>\u{1F552} Login:</strong> ${i.loginTime}</div>

        <div><strong>\u{1F6AA} Logout:</strong> ${i.logoutTime??"Active Now"}</div>

    </div>

    ${i.isCurrent?"":`<button class="btn-logout" onclick="terminateSession(${i.id})">
            Sign Out
        </button>`}

</div>
`,listContainer.appendChild(o)})}function terminateSession(n){if(confirm("Are you sure you want to log out of this device?")){const i=initialSessions.filter(o=>o.id!==n);renderSessions(i)}}renderSessions(initialSessions);
